CREATE TABLE IF NOT EXISTS membership_session_ledger (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), membership_id TEXT NOT NULL REFERENCES customer_memberships(id), appointment_id TEXT, event_type TEXT NOT NULL CHECK(event_type IN ('session_used','session_credit','payment_confirmed','adjustment')), session_delta INTEGER NOT NULL DEFAULT 0, amount_cents INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(business_id,membership_id,appointment_id,event_type));
CREATE INDEX IF NOT EXISTS membership_session_ledger_member_idx ON membership_session_ledger(business_id,membership_id,created_at DESC);
